//! Review regression tests for pkix-ct. Fixtures: tests/fixtures/review/
//! (generated by gen_review_fixtures.py from the sct-oracle fixtures).

#![cfg(feature = "log-list")]

use std::fs;

use der::Decode;
use pkix_ct::{CtLog, CtLogList, SctVerifier, SignedCertificateTimestamp};
use pkix_path::DefaultVerifier;
use x509_cert::Certificate;

fn read(p: &str) -> Vec<u8> {
    fs::read(p).unwrap_or_else(|e| panic!("read {p}: {e}"))
}

fn oracle_logs() -> CtLogList {
    let spki = read("tests/fixtures/sct-oracle/precert-log-spki.der");
    let id: [u8; 32] = read("tests/fixtures/sct-oracle/precert-log-id.bin")
        .try_into()
        .unwrap();
    let mut logs = CtLogList::new();
    logs.insert(CtLog::new(
        id,
        spki,
        "precert-oracle".into(),
        "https://example.invalid/".into(),
        Some(0),
        None,
    ))
    .unwrap();
    logs
}

/// RFC 6962 §3.3 / CABF BR §3.2.2.9 / browser CT policies count
/// independent logs. A leaf whose SCT list repeats one SCT must yield
/// one verified log, not two.
#[test]
fn duplicate_embedded_sct_is_not_counted_twice() {
    let leaf = Certificate::from_der(&read("tests/fixtures/review/leaf-dup-sct.der")).unwrap();
    let issuer =
        Certificate::from_der(&read("tests/fixtures/sct-oracle/precert-issuer.der")).unwrap();
    let v = SctVerifier::new(oracle_logs(), DefaultVerifier);
    let verified = v.verify_embedded_scts(&leaf, &issuer).expect("verify");
    assert_eq!(
        verified.len(),
        1,
        "one SCT from one log was reported {} times: {verified:?}",
        verified.len()
    );
    assert_eq!(v.count_embedded_sct_logs(&leaf, &issuer), Ok(1));
}

#[cfg(feature = "log-list-json")]
fn verify_with_state(state: &str) -> Result<(), pkix_ct::Error> {
    let json = fs::read_to_string(format!("tests/fixtures/review/log-list-{state}.json")).unwrap();
    let logs = CtLogList::from_google_log_list_json(&json).expect("parse log list");
    assert_eq!(logs.len(), 1, "{state} log should be imported");
    let v = SctVerifier::new(logs, DefaultVerifier);
    let sct =
        SignedCertificateTimestamp::from_bytes(&read("tests/fixtures/sct-oracle/precert-sct.bin"))
            .unwrap();
    // SCT timestamp 2025-06-16 is before the 2025-09-01 state change.
    v.verify_sct_for_precert(
        &sct,
        &read("tests/fixtures/sct-oracle/precert-leaf-final.der"),
        &read("tests/fixtures/sct-oracle/precert-issuer.der"),
    )
    .map(|_| ())
}

/// `from_google_log_list_json` documents retired logs as "historical
/// SCTs remain valid", but it leaves `usable_from_ms = None`, which the
/// window check treats as "never usable".
#[cfg(feature = "log-list-json")]
#[test]
fn retired_log_accepts_sct_issued_before_retirement() {
    assert_eq!(verify_with_state("retired"), Ok(()));
}

/// Same for readonly: documented as "still trusted for existing SCTs".
#[cfg(feature = "log-list-json")]
#[test]
fn readonly_log_accepts_sct_issued_before_readonly() {
    assert_eq!(verify_with_state("readonly"), Ok(()));
}

/// `SignedCertificateTimestamp::new` and its fields are public, so an
/// `extensions` longer than the RFC 6962 §3.2 `opaque<0..2^16-1>` bound
/// reaches `build_signed_input_*`, which only `debug_assert!`s the bound
/// (panic in debug, silently truncated u16 length prefix in release).
/// Expected: a typed error, never a panic or a mis-framed signed input.
#[test]
fn oversize_sct_extensions_is_an_error_not_a_panic() {
    let base =
        SignedCertificateTimestamp::from_bytes(&read("tests/fixtures/sct-oracle/precert-sct.bin"))
            .unwrap();
    let sct = SignedCertificateTimestamp::new(
        0,
        base.log_id,
        base.timestamp_ms,
        vec![0u8; 0x1_0001],
        base.hash_alg,
        base.sig_alg,
        base.signature.clone(),
    );
    let v = SctVerifier::new(oracle_logs(), DefaultVerifier);
    let leaf = read("tests/fixtures/sct-oracle/precert-leaf-final.der");
    let issuer = read("tests/fixtures/sct-oracle/precert-issuer.der");
    let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        v.verify_sct_for_precert(&sct, &leaf, &issuer).map(|_| ())
    }));
    assert!(
        r.is_ok(),
        "verify_sct_for_precert panicked on 65537-byte extensions"
    );
    assert_eq!(r.unwrap(), Err(pkix_ct::Error::SctExtensionsTooLong));
    // The public MerkleTreeLeaf builders share the same u16 prefix.
    assert_eq!(
        pkix_ct::merkle_tree_leaf_for_cert(&sct, &leaf),
        Err(pkix_ct::Error::SctExtensionsTooLong)
    );
    assert_eq!(
        pkix_ct::merkle_tree_leaf_for_precert(&sct, &leaf, &issuer),
        Err(pkix_ct::Error::SctExtensionsTooLong)
    );
    // Exactly 2^16 - 1 octets is still legal (not an extensions error).
    let mut max = sct.clone();
    max.extensions.truncate(0xFFFF);
    assert!(pkix_ct::merkle_tree_leaf_for_cert(&max, &leaf).is_ok());
}
